const css=document.createElement("style");css.textContent=`
.vseg{display:inline-flex;border:1px solid var(--bd);border-radius:9px;overflow:hidden;background:var(--glass);backdrop-filter:blur(6px);flex-shrink:0}
.vseg button{border:0;background:transparent;color:var(--ink);padding:6px 12px;font:inherit;font-size:calc(13px*var(--fs));font-weight:700;cursor:pointer;white-space:nowrap}
.vseg button[aria-pressed="true"]{background:var(--acc);color:#0b1220}
.vseg button:focus-visible{outline:2px solid var(--acc);outline-offset:-2px}
.vseg.big{margin:0 0 18px}.vseg.big button{padding:10px 18px;font-size:calc(15px*var(--fs));min-height:44px}
#v2d{position:absolute;inset:0;z-index:3;display:flex;flex-direction:column;background:var(--bg);padding:58px 12px calc(10px + var(--vtp,0px));gap:8px}
#v2d[hidden]{display:none}
#v2dHead{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
#v2dHead h2{font-size:calc(15px*var(--fs));margin:0;color:var(--ink);flex:1;min-width:160px}
#v2dHead select{max-width:230px;background:var(--glass);color:var(--ink);border:1px solid var(--bd);border-radius:8px;padding:6px 8px;font:inherit;font-size:calc(13px*var(--fs))}
#v2dHead select option,#v2dHead select optgroup{background:#12262b;color:#e8eef2}
#v2dChips{display:flex;gap:6px;flex-wrap:wrap}
#v2dChips button{border:1px solid var(--bd);background:var(--glass);color:var(--ink);border-radius:999px;padding:4px 11px;font:inherit;font-size:calc(12px*var(--fs));cursor:pointer}
#v2dChips button[aria-pressed="true"]{border-color:var(--acc);box-shadow:inset 0 0 0 1px var(--acc);font-weight:700}
#v2dNote{font-size:calc(12px*var(--fs));color:var(--ink2,var(--ink));opacity:.85}
#v2dBody{position:relative;flex:1;min-height:0;display:flex;align-items:center;justify-content:center;overflow:hidden}
#v2dWrap{position:relative;display:inline-block;line-height:0;border:1px solid var(--bd);border-radius:12px;overflow:hidden;box-shadow:0 12px 40px rgba(0,0,0,.45);max-width:100%;max-height:100%}
#v2dWrap img{display:block}
#v2dEmpty{text-align:center;color:var(--ink);font-size:calc(14px*var(--fs));line-height:1.6;padding:20px;max-width:460px}
.vmk{position:absolute;width:30px;height:30px;margin:-15px 0 0 -15px;padding:0;border:0;background:transparent;cursor:pointer;line-height:1;z-index:1}
.vmk i{position:absolute;inset:5px;border-radius:50%;background:#ffd54f;color:#0b1220;border:2px solid #0b1220;box-shadow:0 0 0 1.5px rgba(255,255,255,.85),0 1px 6px rgba(0,0,0,.6);font:700 11px/16px system-ui,sans-serif;font-style:normal;text-align:center}
.vmk.on i{background:#fff;box-shadow:0 0 0 3px #ffd54f,0 0 14px #ffd54f}
#v2dCall{position:absolute;inset:0;pointer-events:none;z-index:2}
#v2dLines{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:2;overflow:visible}
.vcl{pointer-events:auto;cursor:pointer;display:flex;gap:7px;align-items:flex-start;text-align:left;background:var(--glass);color:var(--ink);border:1px solid var(--bd);border-radius:9px;padding:5px 9px 5px 6px;font:inherit;font-size:calc(12.5px*var(--fs));line-height:1.3;backdrop-filter:blur(6px);transition:opacity .15s,border-color .15s}
#v2dCall .vcl{position:absolute;left:0;top:0;width:max-content}
.vcl .n{flex:none;min-width:19px;height:19px;border-radius:50%;background:#ffd54f;color:#0b1220;font:700 11px/19px system-ui,sans-serif;text-align:center}
.vcl .en{font-weight:700;display:block}.vcl .hi{display:block;color:var(--hi,#8ee0a7);font-size:.93em;line-height:1.45}
.vcl .fn{display:none;margin-top:2px;font-size:.84em;line-height:1.3;font-weight:400;color:var(--ink);opacity:.82;white-space:normal}
#v2d:not(.tap):not(.compact) .vcl .fn,#v2d .vcl.on .fn{display:block}
body.nofn .vcl .fn{display:none!important}
.vcl.on{border-color:#ffd54f;box-shadow:0 0 0 2px rgba(255,213,79,.45)}
#v2d.hassel .vcl:not(.on){opacity:.45}
#v2d.tap #v2dCall .vcl:not(.on){visibility:hidden}
#v2dLegend .vcl{flex:1 1 230px;max-width:calc(50% - 3px)}
#v2dLegend{display:flex;flex-wrap:wrap;gap:6px;max-height:36%;overflow:auto;justify-content:center;flex:none}
#v2dLegend[hidden]{display:none}
#v2d.narrow #v2dLab{display:none}
#v2dDesc{font-size:calc(12.5px*var(--fs));color:var(--ink);opacity:.9;text-align:center;line-height:1.45;max-height:3.2em;overflow:auto}
body.v2d #tlab,body.v2d #resetv,body.v2d #hud,body.v2d #labels,body.v2d #leaders,body.v2d #fpsm,body.v2d #perfBar,body.v2d #nogl{display:none!important}
#v2dWrap.busy img{opacity:.35}#v2dWrap img{transition:opacity .15s}
#v2dLoad{color:var(--ink);font-size:calc(14px*var(--fs));opacity:.85}
@media (max-width:640px){#v2dHead select{max-width:100%;flex:1}#v2dChips{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:thin;padding-bottom:2px}#v2dChips button{flex:none}}
@media print{.vseg{display:none}}`;
